  const ATMO = { storm: '<i class="a-rain"></i><i class="a-rain b"></i><i class="a-flash"></i>', ash: '<i class="a-sun"></i><i class="a-ash"></i><i class="a-ash b"></i><i class="a-mist"></i>', night: '<i class="a-stars"></i><i class="a-stars b"></i><i class="a-moon"></i><i class="a-fall"></i><i class="a-fall b"></i>', glass: '<i class="a-g g1"></i><i class="a-g g2"></i><i class="a-g g3"></i><i class="a-g g4"></i><i class="a-g g5"></i><i class="a-sheen"></i>', steel: '<i class="a-dawn"></i><i class="a-brush"></i><i class="a-sheen"></i>', pixel: '<i class="a-px"></i><i class="a-grid"></i><i class="a-scan"></i>', ink: '<i class="a-speed"></i><i class="a-half"></i>' };
