  function mascot(s) { try { if (s.skin === 'storm') { const b = (window.L20 && L20.blade && L20.blade()) || 'oathbringer'; return '<img class="masc blade" src="art/blades/s_' + esc(b) + '.png" alt="">'; } if (s.skin === 'ash') return '<span class="masc kel"><i class="pl a"></i><i class="pl b"></i><i class="pl c"></i><img src="art/kelsier_3x.png" alt=""></span>'; } catch (e) {} return ''; }
  function shelf(s) { if (!s.skin) return ''; const P = s.spines || ['#3b5a80', '#7a2f2f', '#3f7a55', '#b08a3e', '#5b4a8c']; return '<div class="shelf">' + s.books.map((b, i) => { const rd = L29.read(b.k), on = L29.started(b.k) && !rd; const hgt = 126 + ((i * 37) % 4) * 9; const lab = b.sp || b.t.replace(/^(A Court of|The) /, ''); return '<button class="spine ' + (rd ? 'rd' : on ? 'on' : 'lk') + '" data-a="book" data-k="' + b.k + '" style="--c:' + P[i % P.length] + ';height:' + hgt + 'px" aria-label="' + esc(b.t) + (rd ? ', ' + W(s).fined.toLowerCase() : on ? ', ' + W(s).on2 : ', sealed') + '"><span>' + esc(lab) + '</span>' + (rd ? '' : on ? '<i class="rib"></i>' : '<em>' + ICON.lock + '</em>') + '</button>'; }).join('') + mascot(s) + '</div>'; }
  const GEMS = ['#4f8fe8', '#aab3bd', '#e0483e', '#eef4f8', '#3fbf7a', '#c23a45', '#d9c9a0', '#a070d8', '#e2a23a', '#ecd84e'];
  const METALS = ['#8b8f96', '#b9c4cf', '#c8ccd0', '#9aa0a8', '#a8b0bb', '#c9a24a', '#c8743c', '#a8733a', '#e0b83a', '#e6d27a', '#9fb7c9', '#b0b8a0', '#d5dbe0', '#aab4be', '#cfd8e0', '#b7a98f'];
  const COURTS = ['#f09ab5', '#3ec6c0', '#e2733a', '#a9dcf5', '#f2c6a8', '#f3d35a', '#8a7cf5'];
  function pips(s, st) { const f = st.n ? st.u / st.n : 0; const row = (cls, cols) => '<div class="pips ' + cls + '">' + cols.map((c, i) => '<i class="' + (f * cols.length >= i + 1 ? 'lit' : f * cols.length > i ? 'half' : '') + '" style="--c:' + c + '"></i>').join('') + '</div>';
    if (s.skin === 'storm') return row('spheres', GEMS); if (s.skin === 'ash') return row('metals', METALS); if (s.skin === 'night') return row('stars', COURTS);
    if (s.skin === 'glass') return '<div class="pips shards">' + s.books.map(b => '<i class="' + (L29.read(b.k) ? 'lit' : L29.started(b.k) ? 'half' : '') + '" style="--c:#bff2d6"></i>').join('') + '</div>';
    return bar(st.u, st.n); }
  // the part switch for the book he is in the middle of
  function where(s) { const b = s.books.find(b => L29.started(b.k) && !L29.read(b.k)); if (!b) { const nb = s.books.find(b => !L29.read(b.k)); if (!nb) return ''; return '<div class="where"><span class="k">Your place</span><p>Next up: <b>' + esc(nb.t) + '</b>. ' + W(s).den + '</p></div>'; }
    if (!b.parts) return '<div class="where"><span class="k">Your place</span><p>' + W(s).on + ' <b>' + esc(b.t) + '</b>. ' + W(s).mark + '</p></div>';
    const p = L29.part(b.k); return '<div class="where"><span class="k">Your place in ' + esc(b.t) + '</span><p>' + W(s).thru + '</p><div class="seg">' + ['Just started'].concat(b.parts).map((n, i) => '<button data-a="part" data-b="' + b.k + '" data-n="' + i + '"' + (p === i ? ' class="on"' : '') + '>' + (i && !b.raw ? '<small>Part ' + NUM[i] + '</small>' : '') + esc(n) + '</button>').join('') + '</div><p class="fine">' + W(s).rest + '</p></div>'; }
  function entryList(s) { const q = V.q.trim().toLowerCase(); let E = (s.e || []).filter(e => entryOpen(s, e)); const all = (s.e || []).length;
    if (V.cat === '~new') E = E.filter(e => isNew(s, e)); else if (V.cat) E = E.filter(e => e.c === V.cat);
    if (q) E = E.filter(e => (e.n + ' ' + tx(e.t, 1) + ' ' + (e.s || []).filter(x => ok(x[0])).map(x => x[1]).join(' ')).toLowerCase().indexOf(q) >= 0);
    if (!E.length) return '<p class="none">' + (q || V.cat ? 'Nothing opened matches that.' : 'Nothing is open yet. ' + W(s).first + ' and its entries appear here.') + '</p>';
    let h = ''; Object.keys(s.cats).forEach(c => { const L = E.filter(e => e.c === c).sort((a, b) => (a.o || 9) - (b.o || 9) || a.n.localeCompare(b.n)); if (!L.length) return; h += '<div class="gh">' + esc(s.cats[c]) + '<small>' + L.length + '</small></div><div class="rows">' + L.map(e => row(s, e)).join('') + '</div>'; });
    const hid = all - (s.e || []).filter(e => entryOpen(s, e)).length; if (hid && !q && !V.cat) h += '<p class="more">' + ICON.lock + ' ' + hid + ' more ' + (hid === 1 ? 'entry is' : 'entries are') + ' sealed until you ' + W(s).further + '.</p>'; return h; }
  function entry(s, e) { if (!e || !entryOpen(s, e)) return '<p class="none">That entry is sealed.</p>'; let sealedN = 0; let h = '<div class="hero ent">' + atmo(s) + '<div class="hc"><span class="k">' + esc(s.cats[e.c] || '') + ' · ' + esc(s.short) + '</span><h1>' + esc(e.n) + '</h1><p class="tag">' + esc(tx(e.t, 1)) + '</p></div></div><div class="secs">';
    (e.s || []).forEach((x, i) => { if (!ok(x[0])) { sealedN++; return; } h += '<div class="sec' + (NEW.has(e.id + '.' + i) ? ' isnew' : '') + '">' + (x[0] ? '<span class="src">' + esc(gateName(x[0])) + (NEW.has(e.id + '.' + i) ? ' · new' : '') + '</span>' : '') + '<p>' + esc(x[1]) + '</p></div>'; });
    h += '</div>'; if (sealedN) h += '<div class="seal">' + ICON.lock + '<span>' + sealedN + ' more ' + (sealedN === 1 ? 'section' : 'sections') + ' sealed. ' + (sealedN === 1 ? 'It opens' : 'They open') + ' ' + W(s).as + '.</span></div>';
    const T = (s.trees || []).filter(t => ok(t.g || '') && t.p.some(p => (p[4] || {}).e === e.id && ok((p[4] || {}).g || ''))); if (T.length) h += '<div class="gh">On the family tree</div>' + T.map(t => tree(s, t, e.id)).join('');
    const R = (e.rel || []).map(id => s.E[id]).filter(x => x && entryOpen(s, x)); if (R.length) h += '<div class="gh">Related</div><div class="rows">' + R.map(x => row(s, x)).join('') + '</div>';
    return h; }
  function sealed(s, st) { const b4 = (() => { try { return L4.all().find(x => x.id === 'lore_' + s.k); } catch (e) { return null; } })();
    let h = '<div class="rows books">' + s.books.map(b => { const n = st.lock[b.k] || 0; const rd = L29.read(b.k), on = L29.started(b.k) && !rd; return '<button class="row bk" data-a="book" data-k="' + b.k + '"><span><b>' + esc(b.t) + '</b><i>' + (rd ? W(s).fined + (n ? ' · ' + n + ' wait on another ' + W(s).item : ' · all of it is open') : on ? W(s).on + ' · ' + n + ' still sealed' : n ? ICON.lock + ' ' + W(s).fin + ' it to open ' + n : W(s).none + ' · nothing sealed behind it') + '</i></span><em class="' + (rd ? 'ok' : on ? 'on' : 'lk') + '">' + (rd ? '✓' : n || '') + '</em></button>'; }).join('') + '</div>';
    if (b4) { const names = ['Bronze', 'Pewter', 'Gold', 'Atium']; h += '<div class="gh">Badge</div><button class="bdg" data-a="badge"><b>' + esc(b4.name) + '</b><i>' + (b4.tier ? names[b4.tier - 1] + ' earned' : 'Not earned yet') + (b4.next ? ' · ' + (b4.next - b4.v) + ' more for ' + names[b4.tier] : '') + '</i><div class="tiers">' + b4.th.map((t, i) => '<span' + (b4.tier > i ? ' class="got"' : '') + '>' + names[i] + '<small>' + t + '</small></span>').join('') + '</div></button>'; }
    return h; }
  function foot(s) { return '<div class="foot">' + (s.src ? 'Checked against ' + s.src.map(x => '<a href="' + esc(x[1]) + '" target="_blank" rel="noopener">' + esc(x[0]) + '</a>').join(', ') + '. Those sites are not spoiler-safe.' : '') + '</div>'; }

  // ---------- family trees: people sit on a grid; only people and ties he has reached are drawn ----------
  function tree(s, t, focus) { const CW = 118, RH = 98, NW = 100, NH = 48, PX = 8, PY = 38; const vis = {}; let hid = 0, maxc = 0, maxr = 0;
    const shown = t.p.filter(p => ok((p[4] || {}).g || '')); hid = t.p.length - shown.length; const minc = shown.reduce((m, p) => Math.min(m, p[3]), 99), minr = shown.reduce((m, p) => Math.min(m, p[2]), 99);
    shown.forEach(p => { const o = p[4] || {}; const c = p[3] - minc, r = p[2] - minr; vis[p[0]] = { id: p[0], n: tx(p[1], 1), x: PX + c * CW, y: PY + r * RH, o }; maxc = Math.max(maxc, c); maxr = Math.max(maxr, r); });
    const W = PX * 2 + maxc * CW + NW, H = PY + maxr * RH + NH + 14; let g = '', un = {};
    (t.u || []).forEach(u => { const a = vis[u[0]], b = vis[u[1]]; if (!a || !b || !ok(u[2] || '')) return; const L = a.x < b.x ? a : b, R = a.x < b.x ? b : a; const y = L.y + NH / 2; const x1 = L.x + NW, x2 = R.x; const k = u[3] || 'm';
      g += k === 'm' ? '<path class="ln" d="M' + x1 + ' ' + (y - 2) + 'H' + x2 + 'M' + x1 + ' ' + (y + 2) + 'H' + x2 + '"/>' : '<path class="ln dash" d="M' + x1 + ' ' + y + 'H' + x2 + '"/>';
      if (u[4]) g += '<text class="lb" x="' + (x1 + x2) / 2 + '" y="' + (y - 6) + '" text-anchor="middle">' + esc(u[4]) + '</text>';
      un[u[0] + '+' + u[1]] = un[u[1] + '+' + u[0]] = { x: (x1 + x2) / 2, y: y + (k === 'm' ? 2 : 0) }; });
    const grp = {}; (t.k || []).forEach(k => { if (!ok(k[2] || '') || !vis[k[1]]) return; let key = k[0], o = null; if (key.indexOf('+') > 0) { const [a, b] = key.split('+'); if (un[key]) o = un[key]; else if (vis[a] && vis[b]) o = { x: (vis[a].x + vis[b].x + NW) / 2, y: vis[a].y + NH / 2 }; else { const one = vis[a] || vis[b]; if (!one) return; key = one.id; o = { x: one.x + NW / 2, y: one.y + NH }; } } else { const one = vis[key]; if (!one) return; o = { x: one.x + NW / 2, y: one.y + NH }; } (grp[key] = grp[key] || { o, c: [] }).c.push(vis[k[1]]); });
    Object.keys(grp).forEach(key => { const G = grp[key]; const rows = {}; G.c.forEach(c => { (rows[c.y] = rows[c.y] || []).push(c); }); Object.keys(rows).forEach(yy => { const L = rows[yy]; const by = +yy - 16; const xs = L.map(c => c.x + NW / 2).concat([G.o.x]); g += '<path class="ln" d="M' + G.o.x + ' ' + G.o.y + 'V' + by + 'M' + Math.min.apply(0, xs) + ' ' + by + 'H' + Math.max.apply(0, xs) + L.map(c => 'M' + (c.x + NW / 2) + ' ' + by + 'V' + c.y).join('') + '"/>'; }); });
    (t.l || []).forEach(l => { const a = vis[l[0]], b = vis[l[1]]; if (!a || !b || !ok(l[3] || '')) return; if (a.y === b.y) { const x1 = a.x + NW / 2, x2 = b.x + NW / 2, y = a.y, top = y - 20; g += '<path class="ln dash" d="M' + x1 + ' ' + y + 'V' + top + 'H' + x2 + 'V' + y + '"/><text class="lb" x="' + (x1 + x2) / 2 + '" y="' + (top - 4) + '" text-anchor="middle">' + esc(l[2]) + '</text>'; } else { const U = a.y < b.y ? a : b, D = a.y < b.y ? b : a; const x1 = U.x + NW / 2, y1 = U.y + NH, x2 = D.x + NW / 2, y2 = D.y; g += '<path class="ln dash" d="M' + x1 + ' ' + y1 + 'L' + x2 + ' ' + y2 + '"/><text class="lb" x="' + ((x1 + x2) / 2 + 4) + '" y="' + ((y1 + y2) / 2) + '">' + esc(l[2]) + '</text>'; } });
    Object.keys(vis).forEach(id => { const p = vis[id]; const dead = p.o.x != null && ok(p.o.x); const can = p.o.e && s.E[p.o.e] && entryOpen(s, s.E[p.o.e]); const nm = String(p.n).split('|'); const tag = tx(p.o.t, 1); const tg = (dead && tag ? '† ' : '') + tag; const tl = tg.length > 19 ? ' textLength="' + (NW - 8) + '" lengthAdjust="spacingAndGlyphs"' : '';
      g += '<g class="nd' + (dead ? ' dead' : '') + (can ? ' can' : '') + (focus && p.o.e === focus ? ' me' : '') + '"' + (can ? ' data-a="entry" data-k="' + p.o.e + '"' : '') + '><rect x="' + p.x + '" y="' + p.y + '" width="' + NW + '" height="' + NH + '"/>' + (nm.length > 1 ? '<text class="nm" x="' + (p.x + NW / 2) + '" y="' + (p.y + 15) + '" text-anchor="middle">' + esc(nm[0]) + '</text><text class="nm" x="' + (p.x + NW / 2) + '" y="' + (p.y + 29) + '" text-anchor="middle">' + esc(nm[1]) + '</text>' : '<text class="nm" x="' + (p.x + NW / 2) + '" y="' + (p.y + (tag ? 20 : 28)) + '" text-anchor="middle">' + esc(nm[0]) + '</text>') + (tag ? '<text class="tg" x="' + (p.x + NW / 2) + '" y="' + (p.y + (nm.length > 1 ? 42 : 36)) + '" text-anchor="middle"' + tl + '>' + esc(tg) + '</text>' : (dead ? '<text class="tg" x="' + (p.x + NW / 2) + '" y="' + (p.y + 40) + '" text-anchor="middle">†</text>' : '')) + '</g>'; });
    return '<div class="card"><div class="ch"><b>' + esc(t.n) + '</b>' + (hid ? '<small>' + ICON.lock + ' ' + hid + ' sealed</small>' : '') + '</div>' + (tx(t.note) ? '<p class="note">' + esc(tx(t.note)) + '</p>' : '') + '<div class="sx"><svg class="tree" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '">' + g + '</svg></div><p class="key"><span class="k1"></span> married <span class="k2"></span> other tie · † dead · tap a name to open it' + (W > 340 ? ' · swipe sideways for the rest' : '') + '</p></div>'; }

  // ---------- charts ----------
  function chart(s, c) { let b = '';
    if (c.type === 'quads') b = '<div class="quads">' + c.groups.map(g => '<div class="quad" style="--q:' + (g.color || 'var(--sa)') + '"><div class="qh"><b>' + esc(g.n) + '</b><span>' + esc(g.sub || '') + '</span></div>' + g.items.map(it => ok(it.g || '') ? '<div class="it"><span class="sym">' + esc(it.sym || '') + '</span><div><b>' + esc(it.n) + '</b>' + (it.tags ? '<span class="tags">' + esc(tx(it.tags, 1)) + '</span>' : '') + (tx(it.who, 1) ? '<span class="who">' + esc(tx(it.who, 1)) + '</span>' : '') + '<p>' + esc(tx(it.fx)) + '</p></div></div>' : '<div class="it lk"><span class="sym">' + ICON.lock + '</span><div><p>Sealed</p></div></div>').join('') + '</div>').join('') + '</div>';
    else if (c.type === 'ring') b = ring(c);
    else if (c.type === 'table') b = '<div class="sx"><table><thead><tr>' + c.cols.map(x => '<th>' + esc(x) + '</th>').join('') + '</tr></thead><tbody>' + c.rows.filter(r => ok(r.g || '')).map(r => '<tr>' + r.c.map((x, i) => { const v = tx(x, 1); return '<td' + (i ? '' : ' class="f"') + '>' + (v ? esc(v) : (Array.isArray(x) ? '<span class="lkc">' + ICON.lock + '</span>' : '')) + '</td>'; }).join('') + '</tr>').join('') + '</tbody></table></div>' + hidNote(c.rows);
    else if (c.type === 'cards') b = '<div class="cards">' + c.items.filter(it => ok(it.g || '')).map(it => '<div class="cd" style="--q:' + (it.color || 'var(--sa)') + '"><b>' + esc(it.n) + '</b>' + (tx(it.sub, 1) ? '<span class="who">' + esc(tx(it.sub, 1)) + '</span>' : '') + (it.lines || []).filter(x => ok(x[0])).map(x => '<p>' + esc(x[1]) + '</p>').join('') + ((it.lines || []).some(x => !ok(x[0])) ? '<p class="lkl">' + ICON.lock + ' more sealed</p>' : '') + '</div>').join('') + '</div>' + hidNote(c.items);
    else if (c.type === 'links') b = '<div class="links">' + c.items.filter(it => ok(it.g || '')).map(it => '<a href="' + esc(it.url) + '" target="_blank" rel="noopener"><b>' + esc(it.n) + '</b><span>' + esc(it.sub || '') + '</span></a>').join('') + '</div>';
    return '<div class="card"><div class="ch"><b>' + esc(c.n) + '</b></div>' + (tx(c.note) ? '<p class="note">' + esc(tx(c.note)) + '</p>' : '') + b + '</div>'; }
  const hidNote = L => { const n = L.filter(x => !ok(x.g || '')).length; return n ? '<p class="more">' + ICON.lock + ' ' + n + ' more ' + (n === 1 ? 'row is' : 'rows are') + ' sealed.</p>' : ''; };
  function ring(c) { const N = c.items.length, cx = 180, cy = 176, R = 112; let g = '<circle class="rg" cx="' + cx + '" cy="' + cy + '" r="' + R + '"/>'; const pt = (i, r) => { const a = (-90 + i * 360 / N) * Math.PI / 180; return [cx + r * Math.cos(a), cy + r * Math.sin(a)]; };
    c.items.forEach((it, i) => { const [x, y] = pt(i, R); const [lx, ly] = pt(i, R + 22); const on = ok(it.g || ''); const an = Math.abs(lx - cx) < 12 ? 'middle' : lx > cx ? 'start' : 'end';
      g += '<circle class="rn' + (on ? '' : ' off') + '" cx="' + x + '" cy="' + y + '" r="13"/><text class="ra" x="' + x + '" y="' + (y + 3.5) + '" text-anchor="middle">' + (on ? esc(it.sym || it.n.slice(0, 2)) : '?') + '</text>' + (on ? '<text class="rl" x="' + lx + '" y="' + (ly + 3 + (ly < cy - R ? -4 : ly > cy + R ? 6 : 0)) + '" text-anchor="' + an + '">' + esc(it.n) + '</text>' : ''); });
    (c.edges || []).forEach((ed, i) => { if (!ok(ed.g || '')) return; const [x, y] = pt(i + .5, i % 2 ? 62 : 86); g += '<text class="re" x="' + x + '" y="' + (y + 3) + '" text-anchor="middle">' + esc(ed.n) + '</text>'; });
    const list = c.items.filter(it => ok(it.g || '')).map(it => '<div class="it"><span class="sym">' + esc(it.sym || it.n.slice(0, 2)) + '</span><div><b>' + esc(it.n) + '</b>' + (tx(it.tags, 1) ? '<span class="tags">' + esc(tx(it.tags, 1)) + '</span>' : '') + (it.lines || []).filter(x => ok(x[0])).map(x => '<p>' + esc(x[1]) + '</p>').join('') + '</div></div>').join('');
    const ed = (c.edges || []).filter(e => ok(e.g || '')).map(e => '<div class="it"><span class="sym sq">' + esc(e.sym || e.n.slice(0, 2)) + '</span><div><b>' + esc(e.n) + '</b><p>' + esc(tx(e.fx)) + '</p></div></div>').join('');
    return '<div class="sx c"><svg class="ringsvg" viewBox="0 0 360 352" width="360" height="352">' + g + '</svg></div>' + (ed ? '<div class="quad" style="--q:var(--sa)"><div class="qh"><b>' + esc(c.edgeName || '') + '</b></div>' + ed + '</div>' : '') + (list ? '<div class="quad" style="--q:var(--sa)"><div class="qh"><b>' + esc(c.itemName || '') + '</b></div>' + list + '</div>' : '') + hidNote(c.items.concat(c.edges || [])); }

  // ---------- in the app: a card on Books, a button on each book of a covered series, a banner when reading opens lore ----------
  L29.seriesFor = t => { for (const s of L29.S) for (const b of s.books) if (titles(b).indexOf(t) >= 0) return s.k; return null; };
  L29.card = function (lib) { L29.flush(); lib = lib || 'books'; const O = orderS(lib); if (!O.length) return ''; const hd = HD[lib] || HD.books; const tu = O.reduce((a, x) => a + x.st.u, 0), tn = O.reduce((a, x) => a + x.st.n, 0);
    return '<div class="d-sec l29-sec" data-lib="' + lib + '"><div class="d-k">' + hd[0] + ' <small>' + tu + ' / ' + tn + ' opened</small></div><div class="l29-row">' + O.map(({ s, st, on }) => { const nx = L29.next(s, st); return '<button class="l29-t" data-l29="' + s.k + '"><b>' + esc(s.short) + '</b><span>' + st.u + ' / ' + st.n + (on ? ' · ' + W(s).on2 : '') + '</span><u><s style="width:' + Math.round(st.u / st.n * 100) + '%"></s></u><i>' + (nx ? esc(nx.b.t) + ': +' + nx.n : 'All opened') + '</i></button>'; }).join('') + '</div><button class="l29-all" data-l29="" data-lib="' + lib + '">Open the ' + hd[0] + ' ›</button></div>'; };
